INSERT INTO `chat_conversations` (`id`, `user_id`, `session_id`, `role`, `message`, `intent`, `entities`, `metadata`, `created_at`) VALUES
(1, 'gaming_user_1761122422080_f6vlqxa4g', 'gaming_user_1761122422080_f6vlqxa4g', 'user', 'PC Gaming dưới 20 triệu', '{\"intent\":\"budget_query\"}', '{\"budget\":20000000,\"platform\":\"PC\"}', '{\"source\":\"gaming-chatbot\"}', '2025-10-22 08:40:26'),
(2, 'gaming_user_1761122422080_f6vlqxa4g', 'gaming_user_1761122422080_f6vlqxa4g', 'bot', 'Tuyệt vời! Với ngân sách này, tôi có thể gợi ý setup gaming chất lượng. 💰 Bạn thích platform nào?\n\n💰 Ngân sách 20.000.000 VNĐ rất hợp lý cho gaming!', '{\"intent\":\"budget_query\"}', NULL, '{\"quickReplies\":[\"Tôi muốn PC gaming 15-20 triệu\",\"Tôi thích Console 10-15 triệu\",\"Tôi cần phụ kiện 5-10 triệu\",\"Tư vấn thêm\"]}', '2025-10-22 08:40:26'),
(3, 'gaming_user_1761122422080_f6vlqxa4g', 'gaming_user_1761122422080_f6vlqxa4g', 'user', 'xbox', '{\"intent\":\"platform_query\"}', '{\"budget\":20000000,\"platform\":\"Xbox\"}', '{\"source\":\"gaming-chatbot\"}', '2025-10-22 08:40:38'),
(4, 'gaming_user_1761122422080_f6vlqxa4g', 'gaming_user_1761122422080_f6vlqxa4g', 'bot', 'Rất tốt! Platform này có những ưu điểm riêng. 🚀 Bạn đã từng sử dụng platform này chưa? Hay đây là lần đầu tiên?\n\n🎮 Xbox là lựa chọn tuyệt vời!', '{\"intent\":\"platform_query\"}', NULL, '{\"quickReplies\":[\"Có, đã từng sử dụng\",\"Không, lần đầu tiên\",\"Tôi có ngân sách 20.000.000 VNĐ\",\"Tư vấn thêm\"]}', '2025-10-22 08:40:38'),
(5, 'gaming_user_1761122422080_f6vlqxa4g', 'gaming_user_1761122422080_f6vlqxa4g', 'user', 'Không, lần đầu tiên', '{}', '{\"budget\":20000000,\"platform\":\"X\"}', '{\"source\":\"gaming-chatbot\"}', '2025-10-22 08:41:03'),
(6, 'gaming_user_1761122422080_f6vlqxa4g', 'gaming_user_1761122422080_f6vlqxa4g', 'bot', 'Chào bạn, với người mới bắt đầu (lần đầu tiên) tham gia thế giới gaming, đây là những lựa chọn phù hợp:\n\n**1. PlayStation 5 (12.000.000 VNĐ - 4.6/5⭐)**\n*   **Tóm tắt:** Máy console thế hệ mới, chuyên biệt cho trải nghiệm game chất lượng cao.\n*   **Ưu điểm:** \"Cắm-là-chơi\" cực dễ sử dụng, không cần lo cấu hình, kho game độc quyền hấp dẫn (Spider-Man, God of War), chi phí ban đầu thấp nhất.\n*   **Nhược điểm:** Chỉ dùng để chơi game, không thể nâng cấp phần cứng, giá game mới thường cao.\n\n**2. Gaming PC RTX 4060 (15.000.000 VNĐ - 4.5/5⭐)**\n*   **Tóm tắt:** PC gaming tầm trung, cân tốt các game 1080p, có thể 1440p ở mức cài đặt phù hợp.\n*   **Ưu điểm:** Đa năng (học tập, làm việc, giải trí), kho game PC khổng lồ với nhiều ưu đãi, linh hoạt nâng cấp về sau.\n*   **Nhược điểm:** Chi phí ban đầu cao hơn console (chưa gồm màn hình, phụ kiện), cần chút kiến thức kỹ thuật cơ bản.\n\n**3. Gaming PC RTX 4070 (20.000.000 VNĐ - 4.7/5⭐)**\n*   **Tóm tắt:** PC gaming cận cao cấp, hiệu năng mạnh mẽ cho trải nghiệm 1440p mượt mà và 4K ở mức khá.\n*   **Ưu điểm:** Trải nghiệm game đồ họa tối ưu, đa năng, tiềm năng nâng cấp lâu dài tốt.\n*   **Nhược điểm:** Chi phí đầu tư ban đầu cao nhất.\n\n**Khuyến nghị:**\nNếu bạn chỉ muốn **\"chơi game\" đơn thuần** mà không bận tâm về kỹ thuật hay mục đích đa nhiệm, **PlayStation 5** là lựa chọn tuyệt vời nhất cho người mới. Dễ dùng, nhiều game hay, giá phải chăng.\n\nNếu bạn muốn một thiết bị **đa năng** để vừa làm việc, học tập vừa chơi game, và có ý định tìm hiểu về PC, **Gaming PC RTX 4060** là điểm khởi đầu hợp lý, mang lại giá trị tốt. RTX 4070 có thể là quá mức cần thiết cho lần đầu tiên, trừ khi bạn có ngân sách lớn và muốn trải nghiệm đỉnh cao ngay lập tức.', '{}', NULL, '{\"quickReplies\":[\"Cảm ơn bạn\",\"Tôi có câu hỏi khác\",\"Bạn có thể giải thích thêm không?\",\"Tôi hiểu rồi\"]}', '2025-10-22 08:41:03'),
