(32, 'gaming_user_1761126391900_um98qgo88', 'gaming_user_1761126391900_um98qgo88', 'bot', 'Tôi rất vui được gợi ý cho bạn! 🎮 Để tôi hiểu rõ hơn về nhu cầu của bạn. Bạn có ngân sách cụ thể nào không? Và bạn thích chơi game gì?', '{\"intent\":\"product_inquiry\"}', NULL, '{\"quickReplies\":[\"Tôi có ngân sách 10-15 triệu\",\"Tôi có ngân sách 20-30 triệu\",\"Tôi thích game FPS\"]}', '2025-10-22 09:46:58'),
