INSERT INTO `chat_conversations` (`id`, `user_id`, `session_id`, `role`, `message`, `intent`, `entities`, `metadata`, `created_at`) VALUES
(110, 'gaming_user_1762164759373_l8a9y20dx', 'gaming_user_1762164759373_l8a9y20dx', 'bot', 'Chào bạn, bên mình đang có các sản phẩm Xbox sau đây:\n\n*   **Xbox Series X**: 11.000.000 VNĐ - Đây là chiếc console mạnh nhất của Xbox, với khả năng chơi game 4K, Game Pass, tương thích ngược và Quick Resume.\n\nBạn có ngân sách khoảng bao nhiêu cho Xbox ạ? Bạn đã có kinh nghiệm chơi game trên console trước đây chưa? Bạn thích chơi thể loại game nào trên Xbox?\n', '{\"intent\":\"gemini_response\"}', NULL, '{\"quickReplies\":[\"Tôi muốn biết thêm\",\"Tư vấn sản phẩm khác\",\"Cảm ơn bạn\",\"Tôi có câu hỏi khác\"]}', '2025-11-03 10:29:59'),
(111, 'gaming_user_1762164759373_l8a9y20dx', 'gaming_user_1762164759373_l8a9y20dx', 'user', 'xbox 7 triệu', '{\"intent\":\"gemini_response\"}', NULL, '{\"source\":\"gemini-ai\"}', '2025-11-03 10:30:22'),
(112, 'gaming_user_1762164759373_l8a9y20dx', 'gaming_user_1762164759373_l8a9y20dx', 'bot', 'Chào bạn,\n\nVới ngân sách 7 triệu đồng, bên mình có sản phẩm **Xbox Series S** với giá **7.000.000 VNĐ**.\n\n**Xbox Series S** là một chiếc console nhỏ gọn, phù hợp cho những ai muốn trải nghiệm game Xbox với mức giá phải chăng. Máy hỗ trợ độ phân giải 1440p, Game Pass và khả năng tương thích ngược với các game Xbox đời trước.\n\nBạn đã có kinh nghiệm chơi game trên console trước đây chưa? Bạn thích chơi thể loại game nào trên Xbox Series S?\n', '{\"intent\":\"gemini_response\"}', NULL, '{\"quickReplies\":[\"Tôi muốn biết giá chi tiết\",\"Sản phẩm đi kèm nào phù hợp?\",\"So sánh với sản phẩm khác\",\"Tư vấn thêm\"]}', '2025-11-03 10:30:22'),
(113, 'gaming_user_1762164759373_l8a9y20dx', 'gaming_user_1762164759373_l8a9y20dx', 'user', 'Sản phẩm đi kèm nào phù hợp?', '{\"intent\":\"gemini_response\"}', NULL, '{\"source\":\"gemini-ai\"}', '2025-11-03 10:34:44'),
(114, 'gaming_user_1762164759373_l8a9y20dx', 'gaming_user_1762164759373_l8a9y20dx', 'bot', 'Chào bạn, để tư vấn sản phẩm đi kèm phù hợp nhất, mình cần biết bạn đang quan tâm đến sản phẩm nào ạ? Ví dụ:\n\n*   **Nếu bạn mua Xbox Series X hoặc PlayStation 5:** Mình gợi ý thêm tay cầm DualSense Controller (1.800.000 VNĐ) để chơi cùng bạn bè, hoặc tai nghe SteelSeries Arctis 7P (3.500.000 VNĐ) để có trải nghiệm âm thanh tốt hơn.\n*   **Nếu bạn mua Gaming PC RTX 4070 Super:** Bạn có thể tham khảo các loại chuột gaming như M55 Wireless Gaming Mouse (75.00 VNĐ) hoặc NIGHTSABRE WIRELESS RGB Gaming Mouse (100.00 VNĐ), cùng với bàn phím gaming như K57 RGB WIRELESS Gaming Keyboard (150.00 VNĐ) để có trải nghiệm chơi game tốt nhất.\n\nBạn cho mình biết bạn đang quan tâm đến sản phẩm nào để mình tư vấn cụ thể hơn nhé!\n', '{\"intent\":\"gemini_response\"}', NULL, '{\"quickReplies\":[\"Tôi muốn biết thêm\",\"Tư vấn sản phẩm khác\",\"Cảm ơn bạn\",\"Tôi có câu hỏi khác\"]}', '2025-11-03 10:34:44'),
(115, 'gaming_user_1762164759373_l8a9y20dx', 'gaming_user_1762164759373_l8a9y20dx', 'user', 'Tư vấn sản phẩm khác', '{\"intent\":\"gemini_response\"}', NULL, '{\"source\":\"gemini-ai\"}', '2025-11-03 10:34:58'),
(116, 'gaming_user_1762164759373_l8a9y20dx', 'gaming_user_1762164759373_l8a9y20dx', 'bot', 'Chào bạn, bạn muốn mình tư vấn sản phẩm nào khác ạ? Bên mình có khá nhiều lựa chọn đấy:\n\n*   **Console:** PlayStation 5 (12.000.000 VNĐ), Xbox Series X (11.000.000 VNĐ)\n*   **Gaming PC:** Gaming PC RTX 4070 Super (28.000.000 VNĐ)\n*   **Phụ kiện:** DualSense Controller (1.800.000 VNĐ), SteelSeries Arctis 7P (3.500.000 VNĐ), ASUS ROG Swift PG27UQ (15.000.000 VNĐ)\n*   **Chuột Gaming:** Nhiều mẫu từ 75.000 VNĐ - 125.000 VNĐ\n*   **Bàn phím Gaming:** Nhiều mẫu giá 100.000 VNĐ - 150.000 VNĐ\n\nBạn có ngân sách khoảng bao nhiêu cho sản phẩm mới này? Bạn đã có kinh nghiệm gaming trước đây chưa? Bạn thích chơi thể loại game nào? Bạn muốn dùng sản phẩm này để làm gì, chơi game, làm việc hay giải trí đa phương tiện?\n', '{\"intent\":\"gemini_response\"}', NULL, '{\"quickReplies\":[\"Tôi muốn biết thêm\",\"Tư vấn sản phẩm khác\",\"Cảm ơn bạn\",\"Tôi có câu hỏi khác\"]}', '2025-11-03 10:34:58'),
(117, 'gaming_user_1762164759373_l8a9y20dx', 'gaming_user_1762164759373_l8a9y20dx', 'user', 'so sánh console với gaming pc', '{\"intent\":\"gemini_response\"}', NULL, '{\"source\":\"gemini-ai\"}', '2025-11-03 10:36:48'),
(118, 'gaming_user_1762164759373_l8a9y20dx', 'gaming_user_1762164759373_l8a9y20dx', 'bot', '', '{\"intent\":\"gemini_response\"}', NULL, '{\"quickReplies\":[\"Tôi muốn biết thêm\",\"Tư vấn sản phẩm khác\",\"Cảm ơn bạn\",\"Tôi có câu hỏi khác\"]}', '2025-11-03 10:36:48'),
(119, 'gaming_user_1762166372119_0l9tlz4mp', 'gaming_user_1762166372119_0l9tlz4mp', 'user', 'PC Gaming dưới 20 triệu', '{\"intent\":\"gemini_response\"}', NULL, '{\"source\":\"gemini-ai\"}', '2025-11-03 10:42:53'),
(120, 'gaming_user_1762166372119_0l9tlz4mp', 'gaming_user_1762166372119_0l9tlz4mp', 'bot', 'Với ngân sách dưới 20 triệu, bạn có thể tập trung vào một PC gaming tầm trung, và tạm thời đầu tư vào các thiết bị ngoại vi sau:\n\n**Các lựa chọn bàn phím phù hợp (dựa trên danh sách):**\n\n*   **K60 PRO TKL RGB Tenkeyless Optical-Mechanical Gaming Keyboard — CORSAIR OPX Switch:** Giá 150.00 VNĐ, thiết kế tenkeyless nhỏ gọn, switch quang học phản hồi nhanh, phù hợp cho game thủ FPS.\n*   **K57 RGB WIRELESS Gaming Keyboard:** Giá 150.00 VNĐ, bàn phím không dây, RGB đẹp mắt, phù hợp cho người thích sự tiện lợi và tính thẩm mỹ.\n*   **K70 CORE TKL WIRELESS RGB Mechanical Gaming Keyboard - Silent Switches:** Giá 100.00 VNĐ, thiết kế tenkeyless, không dây, switch êm ái, phù hợp cho môi trường yên tĩnh.\n\n**Khuyến nghị:**\n\n1.  **K60 PRO TKL RGB:** Nếu bạn ưu tiên hiệu năng và phản hồi nhanh trong game.\n2.  **K57 RGB WIRELESS:** Nếu bạn muốn sự tiện lợi của bàn phím không dây và hiệu ứng RGB bắt mắt.\n3.  **K70 CORE TKL WIRELESS RGB:** Nếu bạn cần một bàn phím yên tĩnh và không dây.\n\nLưu ý: Giá của các sản phẩm trong danh sách đều rất thấp, có thể đây chỉ là giá tượng trưng. Hãy kiểm tra giá thực tế tại cửa hàng trước khi quyết định.', '{\"intent\":\"gemini_response\"}', NULL, '{\"quickReplies\":[\"Tôi muốn biết thêm\",\"Tư vấn sản phẩm khác\",\"Cảm ơn bạn\",\"Tôi có câu hỏi khác\"]}', '2025-11-03 10:42:53'),
(121, 'gaming_user_1762166372119_0l9tlz4mp', 'gaming_user_1762166372119_0l9tlz4mp', 'user', 'pcgaming', '{\"intent\":\"gemini_response\"}', NULL, '{\"source\":\"gemini-ai\"}', '2025-11-03 10:50:23'),
(122, 'gaming_user_1762166372119_0l9tlz4mp', 'gaming_user_1762166372119_0l9tlz4mp', 'bot', 'Chào bạn, mình thấy bạn đang quan tâm đến PC Gaming. Hiện tại bên mình có sản phẩm Gaming PC RTX 4070 Super với giá 28.000.000 VNĐ. Đây là một cấu hình máy tính gaming cao cấp với card RTX 4070 Super, chip Intel i7-13700K, 32GB DDR5 và 1TB NVMe SSD, đảm bảo hiệu năng mạnh mẽ cho mọi tựa game.\n\nBạn có thể cho mình biết thêm về ngân sách dự kiến của bạn là bao nhiêu không? Bạn đã có kinh nghiệm chơi game trên PC trước đây chưa? Bạn thích chơi thể loại game nào? Những thông tin này sẽ giúp mình tư vấn cho bạn cấu hình phù hợp nhất.', '{\"intent\":\"gemini_response\"}', NULL, '{\"quickReplies\":[\"Tôi muốn biết thêm\",\"Tư vấn sản phẩm khác\",\"Cảm ơn bạn\",\"Tôi có câu hỏi khác\"]}', '2025-11-03 10:50:23'),
(123, 'gaming_user_1762166372119_0l9tlz4mp', 'gaming_user_1762166372119_0l9tlz4mp', 'user', 'tôi có khoảng 20 triệu', '{\"intent\":\"gemini_response\"}', NULL, '{\"source\":\"gemini-ai\"}', '2025-11-03 10:50:56'),
